FIELDS = ['id','family','claim','estimand','comparison','independent_unit','data_support_existing_result','remaining_threat_or_failure','next_disposition','source']

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--repo-root',type=Path,default=ROOT);ap.add_argument('--output',type=Path,default=HERE);a=ap.parse_args()
    a.output.mkdir(parents=True,exist_ok=True)
    if (a.output/'PUBLICATION_ALLOWLIST.json').exists(): raise RuntimeError('Frozen publication exists; use --output NEW_DIRECTORY.')
    rows=[dict(zip(FIELDS,r)) for r in DATA]
    for row in rows:
        for key in FIELDS[1:-1]:
            row[key]=re.sub(r'(?<=\d)(?=[a-zåäö])',' ',row[key])
            row[key]=re.sub(r'\b(minst|cirka|endast|före|alla|av|över|samma|vid|efter|med|bland|de|bara|och|respektive|omkring)(?=\d)',r'\1 ',row[key])
    sources=sorted({r['source'] for r in rows}|{'PLAN.md','code/claude_checks/runda12_deklaration.md','code/claude_checks/RATTELSER_2026-11-03.md','output/omxsb_shof_coverage_20261103/audit/REPORT_NEW_POSITION_COVERAGE_SV.txt'})
    ledger=[]
    for p in sources:
        f=(HERE/p) if p.startswith('retention/') else (a.repo_root/p)
        if not f.is_file(): raise FileNotFoundError(f)
        ledger.append({'path':p,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'read_status':'Existing report/declaration, relevant sections; no independent new raw replay in this design inventory'})
    (a.output/'ANALYSIS_FAMILY_MATRIX.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
    lines=['ANALYSFAMILJER — CLAIM → ESTIMAND → JÄMFÖRELSE → OBEROENDE → STÖD → HOT','Teknisk inventering, inte uppsatstext. Familjer är en analytisk gruppering, inte antal hypotesprov. Alla siffror är redan sparade utfall.\n']
    for r in rows:
        lines += [r['id']+' '+r['family']]+[f'{k}: {r[k]}' for k in FIELDS[2:]]+['']
    (a.output/'ANALYSIS_FAMILY_MATRIX.txt').write_text('\n'.join(lines))
    (a.output/'SOURCE_READ_LEDGER.json').write_text(json.dumps({'generated_utc':datetime.now(timezone.utc).isoformat(),'scope':'Known saved OMXSB families in output plus explicitly referenced Claude T-family declarations/results; no claim of auditing every code line or counting every test. Archived repairs are versions, not independent replications.','families':len(rows),'sources':ledger},ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'families':len(rows),'source_files':len(ledger),'new_outcomes_computed':False}))
if __name__=='__main__':main()
